    opp_cnt = int(observation.get("opponent_territory_count", 0) or 0)

    cx, cy = w // 2, h // 2

    def score_pos(x, y):
        # prefer center; slight penalty for proximity to opponent to reduce risk
        return -(abs(x - cx) + abs(y - cy)) + 0.1 * (abs(x - ox) + abs(y - oy))

    def man(x1, y1, x2, y2):
        return abs(x1 - x2) + abs(y1 - y2)

    attack = self_cnt < opp_cnt
    tx, ty = ox, oy
