            tx, ty = min(opp_terr, key=lambda p: man(sx, sy, p[0], p[1]))
    else:
        if unclaimed:
            tx, ty = min(unclaimed, key=lambda p: (man(sx, sy, p[0], p[1]) - 0.01 * score_pos(p[0], p[1])))
        elif opp_terr:
            # if no unclaimed, still try to block by moving toward opponent territory boundary
            tx, ty = min(opp_terr, key=lambda p: man(sx, sy, p[0], p[1]))
        else:
            tx, ty = cx, cy

    best = (10**9, 0, 0)
    for dx, dy in dirs:
        nx, ny = sx + dx, sy + dy
        if not inb(nx, ny):
            continue
        if (nx, ny) in obstacles:
            continue
        # minimize distance to target; prefer diagonal when tied
        d = man(nx, ny, tx, ty)
        diag_pref = 0 if dx == 0 or dy == 0 else -0.01
        # small tie-break: avoid stepping back onto own territory too much only when attacking
        own_pen = 0.02 if attack and (nx, ny) in self_terr else 0.0
        val = (d + own_pen + diag_pref, -abs(dx) - abs(dy), -abs(dx + dy))
        if val < best:
            best = (val, dx, dy)
    return [int(best[1]), int(best[2])]

